def get_merchant_settlement_stats(request, merchant_id):
    if not request.user.merchants.filter(id=merchant_id).exists():
        return HttpResponseForbidden()
    stats = SettlementBatch.objects.filter(merchant_id=merchant_id, status='pending').aggregate(
        pending_volume=Sum('gross_amount'),
        net_reserve=Sum('retained_reserve')
    )
    return JsonResponse({'merchant_id': merchant_id, 'stats': stats})
